/* Readability Lab 0.1.0 — scoped reading styles */
[data-rl-region-cli] {
  --rl-font-size: 18px;
  --rl-line-height: 1.5;
  --rl-font-weight: 400;
  --rl-letter-spacing: normal;
  --rl-word-spacing: normal;
  --rl-measure: 56.5ch;
  --rl-paragraph-gap: 0.75em;
  font-size: var(--rl-font-size) !important;
  line-height: var(--rl-line-height) !important;
  max-width: var(--rl-measure) !important;
  box-sizing: content-box !important;
  margin-inline: auto !important;
}
[data-rl-region-cli] :is(p, li, dd, dt, blockquote, figcaption, td, th, summary, label, address) {
  font-size: var(--rl-font-size) !important;
  line-height: var(--rl-line-height) !important;
  font-weight: var(--rl-font-weight) !important;
  letter-spacing: var(--rl-letter-spacing) !important;
  word-spacing: var(--rl-word-spacing) !important;
  text-align: start !important;
}
[data-rl-region-cli] :is(p) { margin-block: 0 var(--rl-paragraph-gap) !important; }

